const TABLES: Record<Language, Table> = {
  "zh-CN": zhCN,
  "zh-TW": zhTW,
  en,
  "ar": ar,
  "bs": bs,
  "da": da,
  "de": de,
  "es": es,
  "fr": fr,
  "ja": ja,
  "ko": ko,
  "nb": nb,
  "pl": pl,
  "pt-BR": ptBR,
  "ru": ru,
  "th": th,
  "tr": tr,
  "uk": uk,
}

export function t(key: string, params?: Record<string, string | number>): string {
  const value = TABLES[language.value]?.[key] ?? en[key] ?? key
  if (!params) return value
  return Object.entries(params).reduce((out, [name, param]) => out.split(`{${name}}`).join(String(param)), value)
}

/**
 * Every key the menu bar asks for, so it can be built in the main process.
 *
 * This has to stay in step with the L() calls in src/main/menu.ts: a key the
 * menu asks for and this list omits is not an error anywhere, it simply falls
 * back to the English default written beside the call.
 */
const MENU_KEYS = [
  "menu.about", "menu.hide", "menu.hideOthers", "menu.quit",
  "menu.file", "menu.newSession", "menu.newWindow", "menu.openProject", "menu.settings",
  "menu.edit", "menu.undo", "menu.redo",
  "edit.cut", "edit.copy", "edit.paste", "edit.selectAll",
  "menu.view", "menu.palette", "menu.terminal", "menu.sidebar", "menu.files",
  "menu.reload", "menu.devTools",
  "menu.resetZoom", "menu.zoomIn", "menu.zoomOut", "menu.fullscreen",
  "menu.session", "menu.stop", "menu.switchModel", "menu.deleteSession",
  "menu.go", "menu.back", "menu.forward",
  "menu.prevSession", "menu.nextSession", "menu.prevProject", "menu.nextProject",
  "menu.window", "menu.minimize", "menu.zoom", "menu.close",
  // The recovery dialogs in src/main/recovery.ts read the same published
  // table the menu does, so their strings have to be sent with it.
  "desktop.recovery.action.relaunch", "desktop.recovery.action.exportLogs",
  "desktop.recovery.action.keepWaiting", "desktop.recovery.action.quit",
  "desktop.recovery.unresponsive", "desktop.recovery.unresponsive.detail",
  "desktop.recovery.terminated", "desktop.recovery.terminated.detail",
  "desktop.recovery.loadFailed", "desktop.recovery.loadFailed.detail",
  "desktop.recovery.unknown",
]

/**
 * Hands the menu bar its labels in the current language.
 *
 * Menus are built by Electron in the main process, which has no table of its
 * own; sending the finished strings keeps the translations in one place.
 */
export function publishMenuLabels(): void {
  const labels: Record<string, string> = {}
  for (const key of MENU_KEYS) labels[key] = t(key)
  window.mcode?.menuLabels(labels)
}

export function sessionTitle(title: string): string {
  return title === "New session" ? t("session.new") : title
}

/** Relative time, phrased by the active language rather than the OS locale. */
export function ago(value: number): string {
  const seconds = Math.max(1, Math.round((Date.now() - value) / 1000))
  if (seconds < 60) return t("time.secondsAgo", { n: seconds })
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return t("time.minutesAgo", { n: minutes })
  const hours = Math.round(minutes / 60)
  if (hours < 24) return t("time.hoursAgo", { n: hours })
  const days = Math.round(hours / 24)
  if (days < 30) return t("time.daysAgo", { n: days })
  const months = Math.round(days / 30)
  if (months < 12) return t("time.monthsAgo", { n: months })
  return t("time.yearsAgo", { n: Math.round(months / 12) })
}
